add_action( 'init', 'perfectpixel_custom_account_tab_endpoint' );
add_filter( 'woocommerce_get_query_vars', 'perfectpixel_custom_account_tab_query_var' );
add_filter( 'woocommerce_account_menu_items', 'perfectpixel_custom_account_tab_menu', 42 );

function perfectpixel_custom_account_tab_slug() {
	return sanitize_title( '{{custom_tab_slug}}' );
}

function perfectpixel_custom_account_tab_endpoint() {
	$slug = perfectpixel_custom_account_tab_slug();
	add_rewrite_endpoint( $slug, EP_ROOT | EP_PAGES );
	add_action( 'woocommerce_account_' . $slug . '_endpoint', 'perfectpixel_custom_account_tab_content' );
	add_filter( 'woocommerce_endpoint_' . $slug . '_title', 'perfectpixel_custom_account_tab_title' );
}

function perfectpixel_custom_account_tab_query_var( $vars ) {
	$slug          = perfectpixel_custom_account_tab_slug();
	$vars[ $slug ] = $slug;
	return $vars;
}

function perfectpixel_custom_account_tab_menu( $items ) {
	$slug  = perfectpixel_custom_account_tab_slug();
	$after = trim( '{{custom_tab_after}}' );
	$new   = array();
	foreach ( $items as $key => $label ) {
		$new[ $key ] = $label;
		if ( $key === $after ) {
			$new[ $slug ] = '{{custom_tab_label}}';
		}
	}
	if ( ! isset( $new[ $slug ] ) ) {
		$new = array_slice( $new, 0, -1, true ) + array( $slug => '{{custom_tab_label}}' ) + array_slice( $new, -1, null, true );
	}
	return $new;
}

function perfectpixel_custom_account_tab_title() {
	return '{{custom_tab_label}}';
}

function perfectpixel_custom_account_tab_content() {
	echo wp_kses_post( do_shortcode( '{{custom_tab_html}}' ) );
}
